CREATE TABLE IF NOT EXISTS evo_current_runs (id TEXT PRIMARY KEY, unit TEXT NOT NULL CHECK(unit='bike'), state TEXT NOT NULL, next_skip INTEGER NOT NULL DEFAULT 0, requests INTEGER NOT NULL DEFAULT 0, report_ids TEXT, added INTEGER DEFAULT 0, changed INTEGER DEFAULT 0, removed INTEGER DEFAULT 0, error TEXT, started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS evo_current_one_running ON evo_current_runs(unit) WHERE state='running';
CREATE TABLE IF NOT EXISTS evo_current_stage (run_id TEXT NOT NULL REFERENCES evo_current_runs(id), evo_member_id TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(run_id,evo_member_id));
CREATE TABLE IF NOT EXISTS evo_students (unit TEXT NOT NULL, evo_member_id TEXT NOT NULL, display_name TEXT NOT NULL, membership_status TEXT NOT NULL, fitcoins REAL, is_current INTEGER NOT NULL, last_run TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(unit,evo_member_id));
CREATE TABLE IF NOT EXISTS evo_student_categories (unit TEXT NOT NULL, evo_member_id TEXT NOT NULL, category TEXT NOT NULL, subtype TEXT NOT NULL DEFAULT '', source TEXT NOT NULL, PRIMARY KEY(unit,evo_member_id,category,subtype), FOREIGN KEY(unit,evo_member_id) REFERENCES evo_students(unit,evo_member_id));
